exercises.prompt:
What does the generated class name look like in the browser?

/* MovieCard.module.css */
.card { border: 1px solid gray; }

exercises.code:
import styles from './MovieCard.module.css'

function MovieCard() {
  return (
    <div className={/* card class */}>
      <h2 className={/* title class */}>Inception</h2>
    </div>
  )
}

exercises.answer:
import styles from './MovieCard.module.css'

function MovieCard() {
  return (
    <div className={styles.card}>
      <h2 className={styles.title}>Inception</h2>
    </div>
  )
}
